use baal_portfolio_engine::money::{price,money,TICK,SCALE};
use serde::{Serialize,Deserialize};
use serde_json::{Value as V,json};
use std::collections::{BTreeMap,VecDeque};
pub fn clock(v:&V)->Result<i64,String>{chrono::DateTime::parse_from_rfc3339(v.as_str().ok_or("CLOCK")?).map(|v|v.timestamp_millis()).map_err(|_|"CLOCK".into())}
#[derive(Clone,Serialize,Deserialize)]pub struct Quote{pub market:String,pub exchange:String,pub at:i64,pub request:i64,pub received:i64,pub sequence:i64,pub version:String,pub bids:Vec<(i128,i64)>,pub asks:Vec<(i128,i64)>}
impl Quote{pub fn parse(row:&V)->Result<Self,String>{let b=&row["payload"]["book"];let levels=|key:&str|->Result<Vec<(i128,i64)>,String>{b[key].as_array().ok_or("DEPTH")?.iter().map(|l|Ok((price(l["price"].as_str().ok_or("PRICE")?)?,l["quantity"].as_i64().ok_or("QUANTITY")?))).collect()};Ok(Self{market:b["marketId"].as_str().ok_or("MARKET")?.into(),exchange:b["exchangeId"].as_str().ok_or("EXCHANGE")?.into(),at:clock(&row["at"])?,request:clock(&b["requestStartedAt"])?,received:clock(&b["receivedAt"])?,sequence:row["sequence"].as_i64().ok_or("SEQUENCE")?,version:b["versionKey"].as_str().ok_or("VERSION")?.into(),bids:levels("bids")?,asks:levels("asks")?})}}
#[derive(Clone,Serialize,Deserialize)]struct Position{exchange:String,cost:i128,at:i64}
#[derive(Clone,Serialize,Deserialize)]struct Intent{buy:bool,limit:i128,created:i64,sequence:i64,reason:String}
#[derive(Clone,Serialize,Deserialize)]pub struct MedianWallet{ticks:i128,pub cash:i128,pub realized:i128,buys:i128,positions:BTreeMap<String,Position>,pending:BTreeMap<String,Intent>,history:BTreeMap<String,VecDeque<(i64,i128)>>,bulk_history:BTreeMap<String,VecDeque<(i64,i128)>>,use_bulk_history:bool,books:BTreeMap<String,Quote>,consumed:BTreeMap<String,String>,exited:BTreeMap<String,i64>,fills:Vec<V>,counts:BTreeMap<String,u64>}
impl MedianWallet{
 pub fn new(ticks:i128)->Self{Self{ticks,cash:100*SCALE,realized:0,buys:0,positions:BTreeMap::new(),pending:BTreeMap::new(),history:BTreeMap::new(),bulk_history:BTreeMap::new(),use_bulk_history:false,books:BTreeMap::new(),consumed:BTreeMap::new(),exited:BTreeMap::new(),fills:Vec::new(),counts:BTreeMap::new()}}

 pub fn prime_history(&mut self,q:Quote,cutoff:i64)->Result<(),String>{if q.at>=cutoff||cutoff-q.at>3600000||q.request>q.received||q.received>q.at||q.at-q.received>20000{return Ok(())}if let Some(&(bid,_))=q.bids.first(){let h=self.history.entry(q.market).or_default();if h.back().is_some_and(|x|x.0>q.at){return Err("PRIME_CLOCK_ROLLBACK".into())}h.push_back((q.at,bid));}Ok(())}
 pub fn checkpoint(&self)->Result<V,String>{self.assert_funded()?;serde_json::to_value(self).map_err(|_|"MEDIAN_STATE_JSON".into())}
 pub fn restore(state:V,ticks:i128)->Result<Self,String>{let value:Self=serde_json::from_value(state).map_err(|_|"MEDIAN_STATE_JSON")?;if value.ticks!=ticks||![1,2,4].contains(&ticks){return Err("MEDIAN_FIXED_CASE_CHANGED".into())}value.assert_funded()?;Ok(value)}
 pub fn enable_bulk_history(&mut self){self.use_bulk_history=true;}
 pub fn feature_bid(&mut self,market:&str,known_at:i64,bid:i128)->Result<(),String>{if !(TICK..=SCALE-TICK).contains(&bid)||bid%TICK!=0{return Err("BULK_BID_OFF_TICK".into())}let h=self.bulk_history.entry(market.into()).or_default();if h.back().is_some_and(|x|x.0>known_at){return Err("BULK_HISTORY_CLOCK".into())}while h.front().is_some_and(|x|known_at-x.0>3600000){h.pop_front();}h.push_back((known_at,bid));Ok(())}
 fn count(&mut self,key:&str){*self.counts.entry(key.into()).or_default()+=1;}
 pub fn boundary(&mut self,id:Option<&str>){if let Some(id)=id{self.history.remove(id);self.books.remove(id);self.pending.remove(id);}else{self.history.clear();self.books.clear();self.pending.clear();}self.count("source_boundary");}
 fn held(&self)->i128{self.positions.values().map(|p|p.cost).sum()}
 fn reserved(&self,except:&str)->i128{self.pending.iter().filter(|(id,p)|id.as_str()!=except&&p.buy).map(|(_,p)|p.limit).sum()}
 pub fn observe(&mut self,q:Quote,eligible:bool)->Result<(),String>{self.observe_impl(q,eligible,true,false)}
 pub fn observe_with_entry_permission(&mut self,q:Quote,eligible:bool,allow_new_entries:bool)->Result<(),String>{self.observe_impl(q,eligible,allow_new_entries,true)}
 fn observe_impl(&mut self,q:Quote,eligible:bool,allow_new_entries:bool,strict_history:bool)->Result<(),String>{
  let id=q.market.clone();if q.at-q.received>20000||q.request>q.received||q.received>q.at{self.boundary(Some(&id));self.count("stale_book");return Ok(())}self.books.insert(id.clone(),q.clone());
  let h=self.history.entry(id.clone()).or_default();while h.front().is_some_and(|x|q.at-x.0>3600000){h.pop_front();}let values_source=if strict_history&&self.use_bulk_history{self.bulk_history.get(&id)}else{Some(&*h)};let mut prior=values_source.map(|values|values.iter().filter(|x|q.at-x.0<=3600000&&(!strict_history||x.0<q.request)).collect::<Vec<_>>()).unwrap_or_default();if strict_history&&self.use_bulk_history{prior.pop();}let warm=prior.len()>=20&&prior.first().is_some_and(|first|if strict_history{prior.last().unwrap().0-first.0>=1800000}else{q.at-first.0>=1800000});let median=if warm{let mut values:Vec<_>=prior.iter().map(|x|x.1).collect();values.sort();Some(values[values.len()/2])}else{None};
  if let Some(&(bid,_))=q.bids.first(){h.push_back((q.at,bid));}if !eligible{self.pending.remove(&id);self.count("account_unknown_stale_or_excluded");return Ok(())}
  if strict_history{if let Some(position)=self.positions.get(&id){if let Some(&(bid,_))=q.bids.first(){let risk=if bid<=position.cost-4*TICK{Some("loss_limit")}else if q.at-position.at>=7200000{Some("two_hour_risk_exit")}else{None};let pending=self.pending.get(&id);let pending_risk=pending.is_some_and(|p|!p.buy&&p.reason!="profit_target");let override_profit=risk.is_some()&&pending.is_none_or(|p|p.reason=="profit_target");let refresh_risk=pending_risk&&pending.is_some_and(|p|bid<p.limit);if override_profit||refresh_risk{let reason=risk.map(str::to_owned).or_else(||pending.map(|p|p.reason.clone())).unwrap_or_else(||"loss_limit".into());self.pending.insert(id.clone(),Intent{buy:false,limit:(bid-TICK).max(TICK),created:q.at,sequence:q.sequence,reason});self.count(if refresh_risk{"risk_intent_refreshed_new_clock"}else{"risk_overrode_virtual_profit"});}}}}
  let mut filled=false;if let Some(p)=self.pending.get(&id).cloned(){
   if q.at-p.created>120000{self.pending.remove(&id);self.count("intent_expired");}
   else if q.request>p.created&&q.request>=p.created+3000&&q.sequence>p.sequence&&self.consumed.get(&id)!=Some(&q.version){
    let levels=if p.buy{&q.asks}else{&q.bids};let executable=levels.iter().take_while(|(price,_)|if p.buy{*price<=p.limit}else{*price>=p.limit}).find(|(_,quantity)|*quantity/100>=1).map(|x|x.0);
    if let Some(px)=executable{let reserve=self.reserved(&id);let can_buy=!self.positions.contains_key(&id)&&self.positions.len()<3&&self.cash-px-reserve>=90*SCALE&&self.held()+px+reserve<=3*SCALE&&self.buys+px+reserve<=25*SCALE;
     if !p.buy||can_buy{if p.buy{self.cash-=px;self.buys+=px;self.positions.insert(id.clone(),Position{exchange:q.exchange.clone(),cost:px,at:q.at});}else{let position=self.positions.remove(&id).ok_or("UNCOVERED_SALE")?;self.cash+=px;self.realized+=px-position.cost;self.exited.insert(id.clone(),q.at);}self.fills.push(json!({"marketId":id,"exchangeId":q.exchange,"action":if p.buy{"buy"}else{"sell"},"quantity":1,"price":money(px),"fee":"0.000000","availableAtMs":q.at,"requestAtMs":q.request,"sourceSequence":q.sequence,"reason":p.reason,"protectiveLimit":money(p.limit),"counterfactual":true}));self.pending.remove(&id);self.consumed.insert(id.clone(),q.version.clone());self.count("later_raw_receipt_fill");filled=true;}
    }
   }
  }
  if !filled&&!self.pending.contains_key(&id){if let Some(p)=self.positions.get(&id){if let Some(&(bid,_))=q.bids.first(){let reason=if bid>=p.cost+TICK{Some("profit_target")}else if bid<=p.cost-4*TICK{Some("loss_limit")}else if q.at-p.at>=7200000{Some("two_hour_risk_exit")}else{None};if let Some(reason)=reason{let limit=if reason=="profit_target"{(bid-TICK).max(p.cost+TICK)}else{(bid-TICK).max(TICK)};self.pending.insert(id.clone(),Intent{buy:false,limit,created:q.at,sequence:q.sequence,reason:reason.into()});}}}
   else if let(Some(median),Some(&(ask,_)))=(median.filter(|_|allow_new_entries),q.asks.first()){let limit=(ask+TICK).min(SCALE-TICK);let reserve=self.reserved(&id);if median-ask>=self.ticks*TICK&&self.positions.len()+self.pending.values().filter(|p|p.buy).count()<3&&self.cash-limit-reserve>=90*SCALE&&self.held()+limit+reserve<=3*SCALE&&self.buys+limit+reserve<=25*SCALE&&self.exited.get(&id).is_none_or(|at|q.at-at>=900000){self.pending.insert(id.clone(),Intent{buy:true,limit,created:q.at,sequence:q.sequence,reason:"ask_below_earlier_hour_bid_median".into()});self.count("dip_intent");}else{self.count("no_funded_dip");}}
   else{self.count("insufficient_history");}}
  self.assert_funded()?;Ok(())
 }
 pub fn assert_funded(&self)->Result<(),String>{let mut cash=100*SCALE;let mut realized=0;let mut buys=0;let mut lots=BTreeMap::<String,i128>::new();for f in &self.fills{let id=f["marketId"].as_str().unwrap().to_owned();let px=price(f["price"].as_str().unwrap())?;if f["action"]=="buy"{if lots.insert(id,px).is_some(){return Err("DUPLICATE_LOT".into())}cash-=px;buys+=px;}else{realized+=px-lots.remove(&id).ok_or("UNCOVERED_SALE")?;cash+=px;}}if cash!=self.cash||realized!=self.realized||buys!=self.buys||lots.len()!=self.positions.len()||self.positions.iter().any(|(id,p)|lots.get(id)!=Some(&p.cost)){return Err("FIFO_CONSERVATION".into())}let reserved=self.reserved("");if cash-reserved<90*SCALE||self.held()+reserved>3*SCALE||buys+reserved>25*SCALE{return Err("FUNDING".into())}Ok(())}
 pub fn report(&self,at:i64)->V{let mut proceeds=0;let mut complete=true;let positions:Vec<_>=self.positions.iter().map(|(id,p)|{let liquidation=self.books.get(id).filter(|b|at>=b.at&&at-b.received<=20000).and_then(|b|b.bids.iter().find(|(_,q)|*q/100>=1).map(|x|x.0));if let Some(value)=liquidation{proceeds+=value;}else{complete=false;}json!({"marketId":id,"exchangeId":p.exchange,"quantity":1,"cost":money(p.cost),"enteredAtMs":p.at,"estimatedLiquidation":liquidation.map(money)})}).collect();json!({"dipTicks":self.ticks,"cash":money(self.cash),"realizedPnl":money(self.realized),"cumulativeBuys":money(self.buys),"reservedCost":money(self.reserved("")),"fills":self.fills,"closedTrades":self.fills.iter().filter(|f|f["action"]=="sell").count(),"positions":positions,"pendingIntents":self.pending.len(),"estimatedLiquidationPnl":if complete{Some(money(self.cash+proceeds-100*SCALE))}else{None},"counts":self.counts,"officialOrders":0,"profitabilityEstablished":false})}
}
#[cfg(test)]mod tests{use super::*;fn quote(t:i64,bid:i128,ask:i128)->Quote{Quote{market:"1".into(),exchange:"101".into(),at:t,request:t-100,received:t-10,sequence:t,version:t.to_string(),bids:vec![(bid,1000)],asks:vec![(ask,1000)]}}fn warm(w:&mut MedianWallet){for i in 0..=60{w.observe(quote(i*30000,350000,355000),true).unwrap();}}
#[test]fn later_fill_exact_cash_and_covered_exit(){let mut w=MedianWallet::new(2);warm(&mut w);w.observe(quote(1830000,335000,340000),true).unwrap();assert_eq!(w.cash,100*SCALE);w.observe(quote(1840000,335000,340000),true).unwrap();assert_eq!(w.cash,99660000);w.observe(quote(1850000,350000,355000),true).unwrap();w.observe(quote(1860000,350000,355000),true).unwrap();assert_eq!(w.realized,10000);assert_eq!(w.cash,100010000);}
#[test]fn unknown_account_or_gap_cannot_create_fills_or_erase_owned_cost(){let mut w=MedianWallet::new(2);warm(&mut w);w.observe(quote(1830000,335000,340000),false).unwrap();assert_eq!(w.pending.len(),0);w.observe(quote(1840000,335000,340000),true).unwrap();w.observe(quote(1850000,335000,340000),true).unwrap();w.boundary(None);assert_eq!(w.positions.len(),1);assert_eq!(w.cash,99660000);assert_eq!(w.report(1900000)["estimatedLiquidationPnl"],V::Null);}
#[test]fn later_depth_and_fixed_limit_do_not_follow_adverse_quotes(){let mut w=MedianWallet::new(2);warm(&mut w);w.observe(quote(1830000,335000,340000),true).unwrap();w.observe(quote(1840000,345000,350000),true).unwrap();assert_eq!(w.cash,100*SCALE);let mut q=quote(1850000,335000,340000);q.asks[0].1=99;w.observe(q,true).unwrap();assert_eq!(w.cash,100*SCALE);w.assert_funded().unwrap();}
#[test]fn timeout_realizes_loss_and_does_not_hide_it_in_open_inventory(){let mut w=MedianWallet::new(2);warm(&mut w);w.observe(quote(1830000,335000,340000),true).unwrap();w.observe(quote(1840000,335000,340000),true).unwrap();w.observe(quote(9050000,325000,330000),true).unwrap();w.observe(quote(9060000,325000,330000),true).unwrap();assert_eq!(w.realized,-15000);assert!(w.positions.is_empty());}
}

pub fn fixed_policy()->V{json!({"prospectiveRevision":1,"riskPriority":"stop_or_horizon_before_virtual_profit_fill","riskIntentRefresh":"new_intent_new_clock_and_source_on_bid_below_old_limit","stopIsNotGuaranteedLossBound":true,"entryDipTicks":[1,2,4],"historyMs":3600000,"minimumHistorySpanMs":1800000,"minimumHistoryReceipts":20,"latencyMs":3000,"intentLifetimeMs":120000,"maximumHoldMs":7200000,"lossLimitTicks":4,"profitTargetTicks":1,"cooldownMs":900000,"cashReserve":"90.000000","maxExposure":"3.000000","maxMarkets":3,"cumulativeBuyBudget":"25.000000","initialCash":"100.000000","fees":0,"depthFractionBps":100,"fillAdverseTicks":0,"limitCushionTicks":1})}

#[cfg(test)]mod prospective_risk_tests{use super::*;fn q(t:i64,bid:i128,ask:i128)->Quote{Quote{market:"1".into(),exchange:"101".into(),at:t,request:t-100,received:t-10,sequence:t,version:t.to_string(),bids:vec![(bid,1000)],asks:vec![(ask,1000)]}}
#[test]fn prospective_stop_overrides_unsubmitted_profit_and_refresh_never_fills_same_receipt(){let mut w=MedianWallet::new(4);for i in 0..=60{w.prime_history(q(i*30000,350000,355000),1900000).unwrap();}w.observe_with_entry_permission(q(1910000,325000,330000),true,true).unwrap();w.observe_with_entry_permission(q(1915000,325000,330000),true,true).unwrap();assert_eq!(w.cash,99670000);w.observe_with_entry_permission(q(1920000,350000,355000),true,true).unwrap();assert_eq!(w.pending["1"].reason,"profit_target");w.observe_with_entry_permission(q(1925000,305000,310000),true,true).unwrap();assert_eq!(w.positions.len(),1);assert_eq!(w.pending["1"].reason,"loss_limit");assert_eq!(w.pending["1"].created,1925000);w.observe_with_entry_permission(q(1930000,290000,295000),true,true).unwrap();assert_eq!(w.positions.len(),1);assert_eq!(w.pending["1"].created,1930000);w.observe_with_entry_permission(q(1935000,290000,295000),true,true).unwrap();assert!(w.positions.is_empty());assert_eq!(w.realized,-40000);w.assert_funded().unwrap();}
}

pub fn feature_policy()->V{json!({"source":"declared_market_price_observation","feature":"lagged_one_hour_bid_only","excludeMostRecentKnownBulkPoint":true,"knownBeforeOriginalBookRequest":true,"depthAvailable":false,"executable":false})}
